        comp.append((r, c, grid[r][c]))
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            dfs(r + dr, c + dc, comp)

    for i in range(rows):
        for j in range(cols):
            if not visited[i][j] and grid[i][j] != bg:
                comp = []
                dfs(i, j, comp)
